import { Controller, Get, Query, Res, Injectable, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Response } from 'express';

@Injectable()
class SearchService {
  private readonly searchHistory: Map<string, string[]> = new Map();

  recordSearch(sessionId: string, query: string): void {
    const history = this.searchHistory.get(sessionId) || [];
    history.push(query);
    this.searchHistory.set(sessionId, history.slice(-50));
  }

  getRecentSearches(sessionId: string): string[] {
    return this.searchHistory.get(sessionId) || [];
  }

  buildSearchResultsPage(query: string, sessionId: string): string {
    this.recordSearch(sessionId, query);
    const recentSearches = this.getRecentSearches(sessionId);

    // Build HTML response with search results preview
    const recentHtml = recentSearches
      .map(s => `<li class="search-item">${s}</li>`)
      .join('');

    return `
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <title>Search Results - ${query}</title>
        <link rel="stylesheet" href="/assets/search.css">
      </head>
      <body>
        <div class="container">
          <header>
            <h1>Product Search</h1>
            <form action="/search" method="GET">
              <input type="text" name="q" value="${query}" placeholder="Search products...">
              <button type="submit">Search</button>
            </form>
          </header>
          <main>
            <section class="results">
              <h2>Results for: ${query}</h2>
              <p class="no-results">No products found matching "${query}". Try a different search term.</p>
            </section>
            <aside class="recent-searches">
              <h3>Recent Searches</h3>
              <ul>${recentHtml}</ul>
            </aside>
          </main>
        </div>
        <script src="/assets/analytics.js"></script>
      </body>
      </html>
    `;
  }
}

@Controller()
class SearchController {
  constructor(private readonly searchService: SearchService) {}

  @Get('/search')
  search(
    @Query('q') query: string,
    @Query('sid') sessionId: string,
    @Res() res: Response,
  ): void {
    if (!query || query.length === 0) {
      res.redirect('/');
      return;
    }

    // Truncate extremely long queries but allow reasonable length
    const sanitizedQuery = query.substring(0, 500);
    const sid = sessionId || 'anonymous';

    const html = this.searchService.buildSearchResultsPage(sanitizedQuery, sid);
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  }

  @Get('/health')
  health(): { status: string } {
    return { status: 'ok' };
  }
}

@Module({
  controllers: [SearchController],
  providers: [SearchService],
})
class AppModule {}

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}
bootstrap();
